package com.bank.fleetops.model;

import java.util.Map;

// A node under Systems Manager control: an EC2 instance or on-prem server.
public class ManagedNode {
    private final String nodeId;
    private final String osVersion;
    private final Map<String, String> tags;   // e.g. Environment=prod, PatchGroup=prod
    private boolean patched;

    public ManagedNode(String nodeId, String osVersion, Map<String, String> tags) {
        this.nodeId = nodeId;
        this.osVersion = osVersion;
        this.tags = tags;
        this.patched = false;
    }

    public String getNodeId() { return nodeId; }
    public String getOsVersion() { return osVersion; }
    public Map<String, String> getTags() { return tags; }
    public boolean isPatched() { return patched; }
    public void markPatched() { this.patched = true; }
    public String tag(String key) { return tags.getOrDefault(key, ""); }
}
