package com.bank.fleetops.model;

import java.util.List;

// A patch baseline: which patches are approved and how long we wait after release.
public class PatchBaseline {
    private final List<String> approvedClassifications; // Security, Critical
    private final int autoApprovalDelayDays;            // wait N days before approving

    public PatchBaseline(List<String> approvedClassifications, int autoApprovalDelayDays) {
        this.approvedClassifications = approvedClassifications;
        this.autoApprovalDelayDays = autoApprovalDelayDays;
    }

    // Is a given patch classification approved by this baseline?
    public boolean approves(String classification) {
        return approvedClassifications.contains(classification);
    }

    public int getAutoApprovalDelayDays() { return autoApprovalDelayDays; }
}
