package com.bank.fleetops.model;

import java.time.LocalTime;

// The approved time slot during which disruptive patching may run.
public class MaintenanceWindow {
    private final LocalTime start;
    private final LocalTime end;

    public MaintenanceWindow(LocalTime start, LocalTime end) {
        this.start = start;
        this.end = end;
    }

    // Patch Manager must check this before touching production nodes.
    public boolean isOpen(LocalTime now) {
        return !now.isBefore(start) && !now.isAfter(end);
    }
}
