package com.bank.fleetops.ssm;

import com.bank.fleetops.model.ManagedNode;
import java.util.*;
import java.util.logging.Logger;
import java.util.stream.Collectors;

// Represents Systems Manager (SSM): the BROAD operations toolbox for the fleet.
public class FleetOperationsManager {
    private static final Logger log = Logger.getLogger(FleetOperationsManager.class.getName());

    private final List<ManagedNode> fleet;
    private final Map<String, String> parameterStore = new HashMap<>(); // Parameter Store

    public FleetOperationsManager(List<ManagedNode> fleet) {
        this.fleet = fleet;
    }

    public List<ManagedNode> getFleet() { return fleet; }

    // Run Command: execute one command across all nodes matching a tag.
    public void runCommand(String tagKey, String tagValue, String command) {
        List<ManagedNode> targets = fleet.stream()
                .filter(n -> tagValue.equals(n.tag(tagKey)))
                .collect(Collectors.toList());
        log.info(() -> "Run Command on " + targets.size() + " nodes [" + command + "]");
        targets.forEach(n -> log.fine(() -> "  executed on " + n.getNodeId()));
    }

    // Session Manager: shell access with no SSH key and no open inbound port.
    public void openSession(String nodeId) {
        log.info(() -> "Session Manager shell opened on " + nodeId + " (no SSH, no bastion)");
    }

    // Parameter Store: store and fetch encrypted configuration/secrets.
    public void putParameter(String name, String value) { parameterStore.put(name, value); }
    public String getParameter(String name) { return parameterStore.get(name); }

    // Inventory: which nodes run a given OS version (answers audit questions fast).
    public List<ManagedNode> inventoryByOs(String osVersion) {
        return fleet.stream().filter(n -> n.getOsVersion().equals(osVersion))
                .collect(Collectors.toList());
    }
}
