package com.bank.fleetops.patch;

import com.bank.fleetops.model.*;
import com.bank.fleetops.ssm.FleetOperationsManager;
import java.time.LocalTime;
import java.util.List;
import java.util.logging.Logger;
import java.util.stream.Collectors;

// Represents Patch Manager: the NARROW feature INSIDE Systems Manager.
// It depends on the same fleet the FleetOperationsManager controls.
public class PatchManager {
    private static final Logger log = Logger.getLogger(PatchManager.class.getName());

    private final FleetOperationsManager ssm;   // Patch Manager needs SSM to exist first
    private final PatchBaseline baseline;
    private final MaintenanceWindow window;

    public PatchManager(FleetOperationsManager ssm, PatchBaseline baseline, MaintenanceWindow window) {
        this.ssm = ssm;
        this.baseline = baseline;
        this.window = window;
    }

    // Patch all nodes in a patch group, only if the classification is approved
    // AND we are inside the maintenance window.
    public int patchGroup(String patchGroup, String classification, LocalTime now) {
        if (!baseline.approves(classification)) {
            log.warning(() -> "Baseline does NOT approve classification " + classification + " — skipping");
            return 0;
        }
        if (!window.isOpen(now)) {
            log.warning(() -> "Maintenance window CLOSED at " + now + " — refusing to patch production");
            return 0;
        }
        List<ManagedNode> targets = ssm.getFleet().stream()
                .filter(n -> patchGroup.equals(n.tag("PatchGroup")))
                .collect(Collectors.toList());
        targets.forEach(ManagedNode::markPatched);
        log.info(() -> "Patched " + targets.size() + " nodes in group " + patchGroup
                + " (" + classification + ", delay " + baseline.getAutoApprovalDelayDays() + "d)");
        return targets.size();
    }
}
