package com.bank.fleetops;

import com.bank.fleetops.model.*;
import com.bank.fleetops.patch.PatchManager;
import com.bank.fleetops.ssm.FleetOperationsManager;
import java.time.LocalTime;
import java.util.*;
import java.util.logging.*;

public class FleetOpsApplication {
    private static final Logger log = Logger.getLogger(FleetOpsApplication.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        // Build the fleet: Rajesh's savings service + Priya's loan service.
        List<ManagedNode> fleet = List.of(
            new ManagedNode("i-savings01", "Amazon Linux 2", Map.of("Environment","prod","PatchGroup","prod")),
            new ManagedNode("i-savings02", "Amazon Linux 2", Map.of("Environment","prod","PatchGroup","prod")),
            new ManagedNode("i-loan01",    "Amazon Linux 2", Map.of("Environment","prod","PatchGroup","prod")),
            new ManagedNode("i-test01",    "Amazon Linux 2", Map.of("Environment","test","PatchGroup","test"))
        );

        // Systems Manager — the broad toolbox.
        FleetOperationsManager ssm = new FleetOperationsManager(fleet);
        ssm.putParameter("/bank/prod/db-password", "encrypted-value");
        log.info(() -> "Fetched secret from Parameter Store: " + (ssm.getParameter("/bank/prod/db-password") != null));
        ssm.runCommand("Environment", "prod", "systemctl restart bank-api");
        ssm.openSession("i-savings01");
        log.info(() -> "Inventory: nodes on Amazon Linux 2 = " + ssm.inventoryByOs("Amazon Linux 2").size());

        // Patch Manager — the narrow feature inside SSM.
        PatchBaseline baseline = new PatchBaseline(List.of("Security","Critical"), 7);
        MaintenanceWindow window = new MaintenanceWindow(LocalTime.of(2,0), LocalTime.of(5,0));
        PatchManager patchManager = new PatchManager(ssm, baseline, window);

        // Try to patch during the trading day — refused.
        patchManager.patchGroup("prod", "Security", LocalTime.of(11,30));
        // Patch during the approved window — allowed.
        int patched = patchManager.patchGroup("prod", "Security", LocalTime.of(2,30));
        log.info(() -> "Production nodes patched this run: " + patched);
    }
}

